import json, re

# Get all businesses with hours
biz = conn.execute("SELECT gmap_id, name, hours FROM business_description WHERE hours IS NOT NULL").fetchall()
print(len(biz))

WEEKDAYS = {'Monday','Tuesday','Wednesday','Thursday','Friday'}

def closing_after_6pm_on_weekday(hours_str):
    try:
        hours = json.loads(hours_str)
    except:
        return False
    for day, hr in hours:
        if day not in WEEKDAYS:
            continue
        if hr.lower() == 'closed' or 'open 24' in hr.lower():
            if 'open 24' in hr.lower():
                return True
            continue
        # parse closing time
        # format like "6:30AM–6PM" or "9AM–5PM"
        # split on – (en dash)
        parts = re.split(r'[–-]', hr)
        if len(parts) < 2:
            continue
        close = parts[-1].strip()
        m = re.match(r'(\d{1,2})(?::(\d{2}))?\s*(AM|PM)', close, re.IGNORECASE)
        if not m:
            continue
        h = int(m.group(1))
        mi = int(m.group(2)) if m.group(2) else 0
        ampm = m.group(3).upper()
        if ampm == 'PM' and h != 12:
            h += 12
        elif ampm == 'AM' and h == 12:
            h = 0
        # convert to minutes
        close_min = h*60 + mi
        if close_min > 18*60:  # after 6:00 PM
            return True
    return False

qualifying = []
for gmap_id, name, hours_str in biz:
    if closing_after_6pm_on_weekday(hours_str):
        qualifying.append((gmap_id, name, hours_str))
print(len(qualifying))
for q in qualifying[:5]:
    print(q)
